 select id into strict section_id from public.catalog_categories where name=entry->>'category' and merged_into_id is null;
 select id into target_id from public.catalog_items where merged_into_id is null and (name=entry->>'name' or name_en=entry->>'name_en');
 if target_id is null then
  insert into public.catalog_items(name,name_en,category_id,suggested_price,image_url,variants,sort_order)
  values(entry->>'name',entry->>'name_en',section_id,(entry->>'price')::numeric,entry->>'image_url',entry->'variants',next_order) returning id into target_id;
  next_order:=next_order+1;
 end if;
 update public.catalog_items set
  name=entry->>'name',name_en=entry->>'name_en',category_id=section_id,
  suggested_price=(entry->>'price')::numeric,suggested_currency='EGP',
  image_url=coalesce(nullif(image_url,''),entry->>'image_url'),variants=entry->'variants',
  price_min=(entry->>'price')::numeric,
  price_max=coalesce((select max((v->>'price')::numeric) from jsonb_array_elements(entry->'variants') v),(entry->>'price')::numeric),
  ingredients=case when entry->>'name_en'='Avocado Mix' then 'كيوي، أفوكادو، عسل، مكسرات' else ingredients end,
  keywords=array(select distinct k from unnest(coalesce(keywords,'{}')||array[entry->>'name',entry->>'name_en',entry->>'category']) k order by k)
 where id=target_id;
end loop;
