 select id,suggested_price into target_id,base_price from public.catalog_items where name_en=entry->>'name_en' and merged_into_id is null;
 if target_id is null then raise exception 'Missing catalog item %',entry->>'name_en';end if;
 base_price:=coalesce(base_price,(entry->>'price')::numeric);
 update public.catalog_items set
  image_url=coalesce(nullif(image_url,''),entry->>'image_url'),suggested_price=base_price,
  price_min=coalesce(price_min,base_price),price_max=coalesce(price_max,base_price),
  variants=(select coalesce(jsonb_agg(case when coalesce((v->>'price')::numeric,0)<=0 then v||jsonb_build_object('price',case when name_en='Cappuccino' and v->>'name_en'='Double' then 40 else base_price end) else v end),'[]'::jsonb) from jsonb_array_elements(variants) v)
 where id=target_id;
end loop;
update public.catalog_items i set variants=(select jsonb_agg(case when coalesce((v->>'price')::numeric,0)<=0 then v||jsonb_build_object('price',i.suggested_price) else v end) from jsonb_array_elements(i.variants) v)
where i.merged_into_id is null and exists(select 1 from jsonb_array_elements(i.variants) v where coalesce((v->>'price')::numeric,0)<=0);
update public.catalog_items set price_max=(select max((v->>'price')::numeric) from jsonb_array_elements(variants) v)
where name_en='Cappuccino' and merged_into_id is null;
if exists(select 1 from public.catalog_items where merged_into_id is null and (nullif(trim(image_url),'') is null or coalesce(suggested_price,0)<=0)) then raise exception 'Catalog contains incomplete images or prices';end if;
if exists(select 1 from public.catalog_items i cross join lateral jsonb_array_elements(i.variants) v where i.merged_into_id is null and coalesce((v->>'price')::numeric,0)<=0) then raise exception 'Catalog variant price is incomplete';end if;
end $catalog_seed$;
